package fraymus.workspace;
import org.json.*;
import java.util.*;
/** Chat reports the already verified native outcome; it does not infer success from a forecast. */
final class GameSummary118 {
    static String describe(JSONObject a){
        var reasons=new LinkedHashSet<String>();for(Object raw:a.getJSONArray("pickupDecisions")){var row=(JSONObject)raw;reasons.add((row.has("action")?row.getString("action")+": ":"")+row.getString("reason"));}
        return cost(a)+budget(a)+"Constructed and playtested a separate level. Actual finish contact verified. "+a.getInt("repairCount")+" measured repairs; "+a.getInt("wins")+" successful and "+a.getInt("failures")+" failed trials retained. Candidate "+a.getString("candidateId")+". Simple control: "+a.getString("simpleControl")+". Pickup strategy: "+a.optString("pickupStrategy","full")+". Game AI comparison: "+a.getString("existingAI")+"; "+a.getInt("aiPickups")+" power-ups collected, "+a.getInt("aiDamage")+" damage events. "+a.getInt("aiPickupSkips")+" optional pickups declined. "+a.optInt("aiPickupDeferrals",0)+" temporary pickup deferrals; "+a.optInt("aiContactAttempts",0)+" contact recovery attempts. "+opportunity(a)+contact(a)+(reasons.isEmpty()?"":String.join("; ",reasons)+". ")+"The verified candidate is open at its start. No model training or saved-skill admission claimed.";
    }
    private static String cost(JSONObject a){var c=a.optJSONObject("cost125");if(c==null||!c.optBoolean("available"))return "";var t=c.optJSONObject("terminal");return t==null?"":String.format(Locale.ROOT,"First checked outcome: %.2f seconds (%s). Later verification is counted separately; retained cost review is available in task history. ",t.getDouble("seconds"),t.getString("clock"));}
    private static String budget(JSONObject a){var b=a.optJSONObject("pickupChoice124");return b==null?"":String.format(Locale.ROOT,"Budget choice: %s, with %.2f extra seconds allowed per additional pickup. %s. Estimates use matched verified observations, not a hard deadline. ",b.getString("selected"),b.getDouble("allowance"),b.getString("reason"));}
    private static String contact(JSONObject a){var e=a.optJSONObject("aiEnemyLanding");return e==null||e.isEmpty()?"":e.getInt("overrides")+" descending contact corrections; "+e.getInt("edgeStarts")+" supported-edge escapes. Forecasts do not certify success. ";}
    private static String opportunity(JSONObject a){var o=a.optJSONObject("aiOpportunity");if(o==null||o.isEmpty())return "";var reasons=new LinkedHashSet<String>();for(Object raw:o.getJSONArray("decisions"))reasons.add(((JSONObject)raw).getString("reason"));return String.format(Locale.ROOT,"Waited %.2f simulated seconds across %d bounded waits; %d confirmed clear, %d aborted. %d nearby return attempts. ",o.getInt("waitTicks")/60.0,o.getInt("waitStarts"),o.getInt("waitClears"),o.getInt("waitAborts"),o.getInt("revisitStarts"))+(o.has("motion121")?o.getJSONObject("motion121").getInt("reversals")+" observed enemy reversals; "+o.getJSONObject("motion121").getInt("forecastRefusals")+" uncertain clearance forecasts refused. Return attempts alone do not prove collection. ":"")+(reasons.isEmpty()?"":String.join("; ",reasons)+". ");}
}
